+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers to return, understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name, ignoring case and accents, and when its
+ * status is one of {@code statuses}. An empty name or an empty status set does
+ * not restrict anything.
+ *
+ * @param name     free-text name filter; never {@code null}
+ * @param statuses statuses to include; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(statuses);
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        List<String> terms = terms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private List<String> terms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(fold(name)))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
+    static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
